import json,sys,hashlib,html,subprocess,platform
from pathlib import Path
import numpy,torch,mujoco,scipy
O=Path(__file__).resolve().parent;R=O.parents[1];S=R/'svanm2_moe_hardware_audit'
records=json.loads((O/'suite_summary.json').read_text());assert len(records)==120
h=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
files=list(S.rglob('*.py'))+list(S.rglob('*.json'))+list((S/'assets').rglob('*'))
files=sorted(set(p for p in files if p.is_file() and '__pycache__' not in str(p)))
manifest={'scope':'offline only; no robot connection or actuation; no training or deployment','versions':{'python':platform.python_version(),'mujoco':mujoco.__version__,'torch':torch.__version__,'numpy':numpy.__version__,'scipy':scipy.__version__},'rollouts':len(records),'policy_checkpoint_sha256':'440bbb28d554f75db38bfd163351c04ea4a32d9d06764c37b7e6071d41daa5cb','code_and_assets_sha256':{str(p.relative_to(R)):h(p) for p in files},'excluded':'pre_sensor_refresh_runs and invalidated concurrent-edit batch; only runs/ used','reference_sources':{str(p.relative_to(R)):h(p) for p in [O/'original_sim/documentation.md',R/'m2_training_artifacts/hardware_transfer_20260913/moe/env.yaml',R/'m2_training_artifacts/hardware_transfer_20260913/moe_stair_debug_20260921/full_stair_result.json',R/'m2_training_artifacts/hardware_transfer_20260913/moe_stair_debug_20260921/full_stair_policy_trace.npz']}}
cmds=[]
for r in records:
 cmds.append([sys.executable,str(S/'audit/run_suite.py'),'--out','NEW_OUTPUT_DIRECTORY','--terrain',r['terrain'],'--profile',r['profile'],'--seed',str(r['seed']),'--dt',str(r['dt']),'--filter',str(r['filter_s']),'--delay',str(r['delay_s']),'--command',r['command_mode'],'--solref',str(r['contact_timeconst']),'--torque-model',r.get('torque_model','joint')])
(O/'rollout_commands.json').write_text(json.dumps(cmds,indent=2));manifest['rollout_commands_sha256']=h(O/'rollout_commands.json')
video_cards=[];video_metadata={}
for p in sorted((O/'videos').glob('*.mp4')):
 v=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','format=duration:stream=codec_name,width,height,nb_frames','-of','json',str(p)]));assert float(v['format']['duration'])>2;video_metadata[p.name]=v
 title=p.stem.replace('_',' ');rel='videos/'+p.name;sheet=rel.replace('.mp4','_contact_sheet.jpg')
 video_cards.append(f'<article><h3>{html.escape(title)}</h3><video controls preload="metadata" src="{rel}"></video><p><a href="{rel}">Open video</a> · <a href="{sheet}">Four-frame visual review</a></p></article>')
assert len(video_cards)==8
manifest['videos']=video_metadata;(O/'manifest.json').write_text(json.dumps(manifest,indent=2))
plots=[('hardware_joint_angles.png','Hardware: joint angles and sent targets'),('hardware_spectra_gates.png','Hardware spectra, moving windows and MoE weights'),('original_incident_joint_angles.png','Original incident: 20 Hz record'),('terrain_comparison.png','Terrain outcomes and oscillation'),('ablation_comparison.png','Filtering, delay and timestep experiments'),('sim_angles_stairs_up_15_forward.png','15 cm stair: measured, sent and unclamped targets'),('sim_angles_flat_lateral.png','Flat sideways joint curves'),('sim_angles_slope_up_20_forward.png','20 degree ascent joint curves'),('sim_angles_rough_3cm_forward.png','Rough terrain joint curves')]
plotcards=''.join(f'<article><h3>{html.escape(title)}</h3><a href="{p}"><img loading="lazy" src="{p}" alt="{html.escape(title)}"></a></article>' for p,title in plots)
text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SVAN M2 — MoE jitter audit</title><style>body{font:17px/1.55 system-ui,sans-serif;color:#18232c;background:#f5f7fa;max-width:1400px;margin:35px auto;padding:0 25px}h1{font-size:34px;line-height:1.2}h2{margin-top:45px}h3{font-size:17px}a{color:#065b9d}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(410px,1fr));gap:24px}article{background:white;border:1px solid #dae1e7;border-radius:10px;padding:18px}video,img{display:block;width:100%;height:auto}p{max-width:1050px}.note{background:#e5edf5;padding:16px;border-left:4px solid #397397}@media(max-width:500px){.grid{grid-template-columns:1fr}}</style><h1>SVAN M2 · MoE 90k jitter audit</h1><p>120 offline rollouts, two saved hardware runs, eight trajectory videos. No robot commands, deployment or retraining.</p><p class="note">The original simulator did not match deployed target limits. The isolated implementation corrects the control contract; physical actuator and contact parameters remain partly unmeasured. Stair ascent remains unreliable. Smoothing is experimental, and current 0.6 m/s lateral commands exceed the saved ±0.3 m/s training range.</p><p><a href="REPORT.md">Detailed findings and proposed changes</a> · <a href="../../svanm2_moe_hardware_audit/README.md">Run the isolated simulator</a> · <a href="suite_summary.csv">All outcomes (CSV)</a> · <a href="manifest.json">Provenance and verification</a></p><h2>Recorded simulation trajectories</h2><p>These are saved-state replays at the displayed speed, using the original 5 ms physics comparison. “Hardware” labels mean deployed target bounds, not hardware footage. Outcomes are determined over the full episode. Stair films end at the offline tip threshold. The filtered stair clip demonstrates why smoothing was not selected as a fix.</p><div class="grid">'''+''.join(video_cards)+'''</div><h2>Joint curves and diagnostics</h2><p>Click any figure for full resolution. Hardware terrain was not labelled. The 8–30 Hz measure includes gait harmonics and impacts; it is not by itself a success criterion.</p><div class="grid">'''+plotcards+'</div></html>'
(O/'index.html').write_text(text)
print(json.dumps({'rollouts':len(records),'videos':len(video_cards),'frozen_files':len(files),'index':str(O/'index.html')},indent=2))
